def count_scores(rows: list[dict], low: int, high: int) -> int:
    return sum(low <= row.get('score', 0) <= high for row in rows)
```

```python
def count_events(events: list[tuple[int, str]], start: int, end: int) -> int:
    return sum(start <= timestamp <= end for timestamp, label in events)
```

```python
def sum_payments(payments: list[dict], first_day: int, last_day: int) -> int:
    return sum(payment['amount'] for payment in payments if first_day <= payment['day'] <= last_day)
```

```python
def sum_readings(readings: list[tuple[int, int]], low: int, high: int) -> int:
    return sum(value for time, value in readings if low <= time <= high)
```

```python
def sum_weights(items: list[dict], min_key: int, max_key: int) -> int:
    return sum(item['weight'] for item in items if min_key <= item['key'] <= max_key)
